<script>
// ── Trending Carousel ──
const trendingData = [
  {rank:1,title:"Bloodhounds",genre:"Action Thriller",color:"#1a1a2e"},
  {rank:2,title:"BEEF",genre:"Dark Comedy",color:"#2d1b2e"},
  {rank:3,title:"XO, Kitty",genre:"Romantic Comedy",color:"#1b2e1a"},
