  {rank:7,title:"Agent from Above",genre:"Spy Thriller",color:"#2e2e1a"},
  {rank:8,title:"Boyfriend on Demand",genre:"Romantic Comedy",color:"#2e1a2e"},
  {rank:9,title:"KPop Demon Hunters",genre:"Fantasy Action",color:"#1a2e3e"},
  {rank:10,title:"Emily in Paris",genre:"Comedy Drama",color:"#2e1e1e"}
];

function buildCarousel(){
  const carousel = document.getElementById('trendingCarousel');
  carousel.innerHTML = trendingData.map(t => `
    <div class="trending-card" role="listitem" aria-label="Rank ${t.rank}: ${t.title}">
      <div class="poster" style="background:linear-gradient(145deg, ${t.color}, ${t.color}dd)">
        <span class="rank">${t.rank}</span>
        <div class="title-overlay">
